package nexusbench

import (
	"context"
	"encoding/json"
	"fmt"
	"slices"
	"strings"
)

// Op is what a run of the bench is about to do; it decides which checks the
// preflight makes.
type Op int

const (
	OpUp Op = iota
	OpProvision
	OpDown
	OpStatus
)

// PreflightResult is what a successful preflight learned about the cluster.
type PreflightResult struct {
	// NamespaceExists is true when the bench namespace is there.
	NamespaceExists bool
	// NamespaceOurs is true when it carries our managed-by label.
	NamespaceOurs bool
	// NodeIP is the InternalIP of the first node that reports one; empty when
	// none does, which is not an error (the other hosts still work). It is not
	// read for OpDown.
	NodeIP string
}

const (
	// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
	// puts on the namespace; down deletes a namespace only when it carries it.
	managedByLabel = "app.kubernetes.io/managed-by"
	managedByValue = "devdesk-nexus-bench"

	// nexusServiceName is the Service 30-service.yaml.tmpl creates.
	nexusServiceName = "nexus"

	// requestTimeout bounds every call that reaches the API server.
	requestTimeout = "--request-timeout=10s"
)

// permissionScope says where a can-i question applies.
type permissionScope int

const (
	scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
	scopeNamespace                        // -n <namespace>
	scopeAll                              // -A
)

// permission is one "kubectl auth can-i" question the preflight asks.
type permission struct {
	verb, resource string
	scope          permissionScope
}

// permissionsByOp is the list F2 of the plan: what each operation needs. An
// operation absent from the map (status) writes nothing and asks nothing.
var permissionsByOp = map[Op][]permission{
	OpUp: {
		{"create", "namespaces", scopeCluster},
		{"create", "persistentvolumeclaims", scopeNamespace},
		{"create", "services", scopeNamespace},
		{"create", "deployments", scopeNamespace},
		{"create", "secrets", scopeNamespace},
		{"create", "pods/exec", scopeNamespace},
		{"list", "services", scopeAll},
	},
	OpProvision: {{"create", "pods/exec", scopeNamespace}},
	OpDown:      {{"delete", "namespaces", scopeCluster}},
}

// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
// returns what it learned. Nothing is written to the cluster, whatever the
// outcome: a failure here means no write was ever issued. The checks run in a
// fixed order and stop at the first failure, so nothing is asked of a cluster
// the context does not reach:
//
//  1. the parameters (no call at all)
//  2. the context is in the kubeconfig
//  3. the API server answers /readyz
//  4. the can-i questions of the operation
//  5. the namespace: absent, ours, or foreign
//  6. up only: no other Service holds one of our NodePorts
//  7. all but down: the InternalIP of the node
//
// Every failure is a *BenchError.
func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
	var res PreflightResult
	if err := p.Validate(); err != nil {
		return res, err
	}
	pf := preflight{r: r, p: p}
	if err := pf.checkContext(ctx); err != nil {
		return res, err
	}
	if err := pf.checkReachable(ctx); err != nil {
		return res, err
	}
	for _, perm := range permissionsByOp[op] {
		if err := pf.checkPermission(ctx, perm); err != nil {
			return res, err
		}
	}
	res, err := pf.checkNamespace(ctx, op)
	if err != nil {
		return res, err
	}
	if op == OpUp {
		if err := pf.checkNodePorts(ctx); err != nil {
			return res, err
		}
	}
	if op != OpDown {
		if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
			return res, err
		}
	}
	return res, nil
}

type preflight struct {
	r Runner
	p Params
}

// local runs a call that does not reach the API server.
func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
	out, errOut, err := pf.r.Run(ctx, nil, args...)
	return string(out), string(errOut), err
}

// remote runs a call that reaches the API server, under a request timeout.
func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
	return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
}

// command is the kubectl command line a user can run to repeat a call.
func (pf preflight) command(args ...string) string {
	return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
}

// failure turns a failed kubectl call into a BenchError whose kind comes from
// the stderr. Neither the stderr nor the sub-process error reaches the message.
func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
	kind := classifyKubectl(stderr)
	reason := "kubectl failed"
	switch kind {
	case Forbidden:
		reason = "the API server refused the request (forbidden)"
	case ClusterUnreachable:
		reason = "the cluster did not answer"
	}
	return &BenchError{
		Kind:  kind,
		Cause: "could not " + what + ": " + reason,
		Check: pf.command(args...),
		Err:   err,
	}
}

func (pf preflight) checkContext(ctx context.Context) error {
	args := []string{"config", "get-contexts", "-o", "name"}
	out, errOut, err := pf.local(ctx, args...)
	if err != nil {
		return pf.failure("list the kubeconfig contexts", args, errOut, err)
	}
	for _, line := range strings.Split(out, "\n") {
		if strings.TrimSpace(line) == pf.p.Context {
			return nil
		}
	}
	return &BenchError{
		Kind:  ContextNotFound,
		Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
		Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
	}
}

func (pf preflight) checkReachable(ctx context.Context) error {
	args := []string{"get", "--raw", "/readyz"}
	_, errOut, err := pf.remote(ctx, args...)
	if err == nil {
		return nil
	}
	// A refusal (an expired token, a 403) is not an absent cluster: say so.
	// Anything else, classified or not, means the server did not answer.
	if classifyKubectl(errOut) == Forbidden {
		return pf.failure("reach the API server", args, errOut, err)
	}
	return &BenchError{
		Kind:  ClusterUnreachable,
		Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
		Check: pf.command(args...),
		Err:   err,
	}
}

// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
// non-zero exit, so the answer is read before the error.
func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
	args := []string{"auth", "can-i", perm.verb, perm.resource}
	where := "cluster-wide"
	switch perm.scope {
	case scopeNamespace:
		args = append(args, "-n", pf.p.Namespace)
		where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
	case scopeAll:
		args = append(args, "-A")
		where = "in all namespaces"
	}
	out, errOut, err := pf.remote(ctx, args...)
	answer := strings.TrimSpace(out)
	switch {
	case strings.HasPrefix(answer, "no"):
		return &BenchError{
			Kind:  Forbidden,
			Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
			Check: pf.command(args...),
			Err:   err,
		}
	case err == nil && strings.HasPrefix(answer, "yes"):
		return nil
	}
	return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
}

// namespaceObject is the part of a Namespace the preflight reads.
type namespaceObject struct {
	Metadata struct {
		Labels map[string]string `json:"labels"`
	} `json:"metadata"`
}

func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
	var res PreflightResult
	ns := pf.p.Namespace
	args := []string{"get", "namespace", ns, "-o", "json"}
	out, errOut, err := pf.remote(ctx, args...)
	switch {
	case err != nil && isNotFound(errOut):
		// Absent: only provision and status need it.
		if op == OpProvision || op == OpStatus {
			return res, &BenchError{
				Kind:  NamespaceMissing,
				Cause: fmt.Sprintf("namespace %q does not exist", ns),
				Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
				Err:   err,
			}
		}
		return res, nil
	case err != nil:
		return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
	}

	var obj namespaceObject
	if err := json.Unmarshal([]byte(out), &obj); err != nil {
		return res, &BenchError{
			Kind:  Unclassified,
			Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
			Check: pf.command(args...),
			Err:   err,
		}
	}
	res.NamespaceExists = true
	res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
	if !res.NamespaceOurs {
		return res, &BenchError{
			Kind:  NamespaceForeign,
			Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
			Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
		}
	}
	return res, nil
}

// serviceList is the part of a Service list the preflight reads.
type serviceList struct {
	Items []struct {
		Metadata struct {
			Name      string `json:"name"`
			Namespace string `json:"namespace"`
		} `json:"metadata"`
		Spec struct {
			Ports []struct {
				NodePort int `json:"nodePort"`
			} `json:"ports"`
		} `json:"spec"`
	} `json:"items"`
}

// checkNodePorts reads every Service of the cluster: the list of taken
// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
// them: that is a second up.
func (pf preflight) checkNodePorts(ctx context.Context) error {
	args := []string{"get", "services", "-A", "-o", "json"}
	out, errOut, err := pf.remote(ctx, args...)
	if err != nil {
		return pf.failure("list the Services of the cluster", args, errOut, err)
	}
	var list serviceList
	if err := json.Unmarshal([]byte(out), &list); err != nil {
		return &BenchError{
			Kind:  Unclassified,
			Cause: "kubectl answered with something that is not a Service list",
			Check: pf.command(args...),
			Err:   err,
		}
	}
	var taken []string
	for _, svc := range list.Items {
		if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
			continue
		}
		for _, port := range svc.Spec.Ports {
			if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
				taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
			}
		}
	}
	if len(taken) > 0 {
		return &BenchError{
			Kind:  NodePortTaken,
			Cause: "NodePort " + strings.Join(taken, ", "),
			Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
		}
	}
	return nil
}

// nodeList is the part of a Node list the preflight reads.
type nodeList struct {
	Items []struct {
		Status struct {
			Addresses []struct {
				Type    string `json:"type"`
				Address string `json:"address"`
			} `json:"addresses"`
		} `json:"status"`
	} `json:"items"`
}

// nodeIP returns the first InternalIP any node reports, or "" when none does.
func (pf preflight) nodeIP(ctx context.Context) (string, error) {
	args := []string{"get", "nodes", "-o", "json"}
	out, errOut, err := pf.remote(ctx, args...)
	if err != nil {
		return "", pf.failure("read the nodes", args, errOut, err)
	}
	var nodes nodeList
	if err := json.Unmarshal([]byte(out), &nodes); err != nil {
		return "", &BenchError{
			Kind:  Unclassified,
			Cause: "kubectl answered with something that is not a Node list",
			Check: pf.command(args...),
			Err:   err,
		}
	}
	for _, node := range nodes.Items {
		for _, addr := range node.Status.Addresses {
			if addr.Type == "InternalIP" {
				return addr.Address, nil
			}
		}
	}
	return "", nil
}
package nexusbench

import "strings"

// ErrKind says which of the failures of the bench (D-F) a BenchError is. The
// zero value is Unclassified on purpose: an error nobody classified must not
// pass for the first named kind.
type ErrKind int

// The kinds of D-F, in the order the bench meets them.
const (
	// Unclassified is a failure none of the other kinds describes.
	Unclassified ErrKind = iota
	KubectlMissing
	ContextNotFound
	ClusterUnreachable
	Forbidden
	NamespaceForeign
	NamespaceMissing
	NodePortTaken
	AdmissionDenied
	PodPending
	ImagePull
	Crash
	Deadline
	RESTUnreachable
	ProvisionFailed
)

// BenchError is the one error type of the bench: a probable cause and what to
// check, both in English and both free of secrets. Err is the underlying error,
// kept for errors.Is and errors.As; Error never prints it, because the text of
// a failed sub-process can carry a credential.
type BenchError struct {
	Kind  ErrKind
	Cause string
	Check string
	Err   error
}

// Error returns "<Cause>. Check: <Check>".
func (e *BenchError) Error() string {
	return e.Cause + ". Check: " + e.Check
}

// Unwrap returns the underlying error, or nil when there is none.
func (e *BenchError) Unwrap() error { return e.Err }

// classifyKubectl maps the stderr of a failed kubectl call to a kind. The text
// of kubectl changes between versions, so this is a fallback for the cases the
// structured calls (exit status, JSON) cannot tell apart; a text it does not
// know is Unclassified.
func classifyKubectl(stderr string) ErrKind {
	s := strings.ToLower(stderr)
	switch {
	// The more specific reason wins: a webhook refusal is reported by the API
	// server as Forbidden too.
	case strings.Contains(s, "admission webhook") && strings.Contains(s, "denied"):
		return AdmissionDenied
	case strings.Contains(s, "provided port is already allocated"),
		strings.Contains(s, "provided port is not in the valid range"):
		return NodePortTaken
	case strings.Contains(s, "forbidden"):
		return Forbidden
	case strings.Contains(s, "unable to connect to the server"),
		strings.Contains(s, "connection refused"),
		strings.Contains(s, "i/o timeout"),
		strings.Contains(s, "tls handshake timeout"):
		return ClusterUnreachable
	}
	return Unclassified
}

// isNotFound reports whether stderr is the kubectl answer for an absent object.
func isNotFound(stderr string) bool {
	return strings.Contains(stderr, "(NotFound)")
}
package nexusbench

import (
	"context"
	"time"
)

// Clock is the time the waits of the bench read and spend. Tests swap it for a
// fake that never waits, so no test sleeps for real.
type Clock interface {
	// Now returns the current time.
	Now() time.Time
	// Sleep waits for d, or until ctx is done. It returns ctx.Err() when ctx is
	// done, before sleeping if it already was, and nil after the whole wait. A
	// duration of zero or less returns at once (after the ctx check).
	Sleep(ctx context.Context, d time.Duration) error
}

// realClock is the Clock of the command: the wall clock.
type realClock struct{}

// NewClock returns the real clock.
func NewClock() Clock { return realClock{} }

// Now implements Clock.
func (realClock) Now() time.Time { return time.Now() }

// Sleep implements Clock.
func (realClock) Sleep(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if d <= 0 {
		return nil
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

package nexusbench

import (
	"bytes"
	"context"
	"os/exec"
)

// Runner runs one kubectl command. args are the arguments after "kubectl" and
// carry no --context: the runner adds it. stdin is sent to the command when it
// is not empty. Both streams are returned even on failure, because the stderr
// of a failed call is what classifyKubectl reads.
type Runner interface {
	Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error)
}

// execRunner runs the kubectl found on PATH against one context.
type execRunner struct {
	path    string
	context string
}

// NewExecRunner finds kubectl on PATH and returns a Runner that passes
// "--context <kubeContext>" to every call. It fails with a KubectlMissing
// BenchError when kubectl is not installed. This is the one place of the
// package that starts a process.
func NewExecRunner(kubeContext string) (Runner, error) {
	path, err := exec.LookPath("kubectl")
	if err != nil {
		return nil, &BenchError{
			Kind:  KubectlMissing,
			Cause: "kubectl was not found on PATH",
			Check: "run `mise install` to get kubectl, then `kubectl version --client`",
			Err:   err,
		}
	}
	return &execRunner{path: path, context: kubeContext}, nil
}

// Run implements Runner.
func (r *execRunner) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
	full := append([]string{"--context", r.context}, args...)
	cmd := exec.CommandContext(ctx, r.path, full...) //nolint:gosec // the binary is the kubectl found on PATH and the arguments are built by this package from validated parameters
	if len(stdin) > 0 {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var out, errOut bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errOut
	err = cmd.Run()
	return out.Bytes(), errOut.Bytes(), err
}
package nexusbench

import (
	"bytes"
	"embed"
	"fmt"
	"strconv"
	"text/template"
)

//go:embed manifests/*.yaml.tmpl
var manifestFS embed.FS

// Manifest files in the order Render writes them: the Namespace comes first so
// that an apply creates it before the objects it holds.
const (
	namespaceTemplate = "00-namespace.yaml.tmpl"
)

var manifestTemplates = []string{
	namespaceTemplate,
	"10-pvc.yaml.tmpl",
	"20-deployment.yaml.tmpl",
	"30-service.yaml.tmpl",
}

// templates parses the embedded manifests. quote is the only function they can
// call, and it is how every string value reaches the output.
var templates = template.Must(template.New("manifests").
	Funcs(template.FuncMap{"q": quote}).
	Option("missingkey=error").
	ParseFS(manifestFS, "manifests/*.yaml.tmpl"))

// quote writes a string as a YAML double-quoted scalar. A Go string literal is
// valid YAML double-quoted syntax (the escapes \a \b \t \n \v \f \r \" \\ \xNN
// \uNNNN \UNNNNNNNN are common to both), so the value is always read back as the
// same string, never as a number, a boolean, a null or a mapping.
func quote(s string) string { return strconv.Quote(s) }

// manifestData is what the templates see: the validated values the manifests
// carry, and nothing else.
type manifestData struct {
	Namespace                                        string
	Image                                            string
	CPURequest, CPULimit, MemoryRequest, MemoryLimit string
	StorageSize, JVMOpts                             string
	HTTPNodePort, DockerNodePort                     int
}

func newManifestData(p Params) manifestData {
	return manifestData{
		Namespace:      p.Namespace,
		Image:          p.ImageRef(),
		CPURequest:     p.CPURequest,
		CPULimit:       p.CPULimit,
		MemoryRequest:  p.MemoryRequest,
		MemoryLimit:    p.MemoryLimit,
		StorageSize:    p.StorageSize,
		JVMOpts:        p.JVMOpts,
		HTTPNodePort:   p.HTTPNodePort,
		DockerNodePort: p.DockerNodePort,
	}
}

// Render returns the manifests of the bench as a multi-document YAML stream: the
// Namespace, the PersistentVolumeClaim, the Deployment and the Service, in that
// order. The parameters are validated first, and the same parameters always
// give the same bytes. Parameters the manifests do not carry (context, upstream
// URL, EULA, hosts, timeouts, paths) do not change the output.
func Render(p Params) ([]byte, error) {
	return render(p, manifestTemplates)
}

// RenderNamespace returns the Namespace document alone, the first one of Render.
func RenderNamespace(p Params) ([]byte, error) {
	return render(p, []string{namespaceTemplate})
}

func render(p Params, names []string) ([]byte, error) {
	if err := p.Validate(); err != nil {
		return nil, err
	}
	data := newManifestData(p)
	var out bytes.Buffer
	for i, name := range names {
		if i > 0 {
			out.WriteString("---\n")
		}
		if err := templates.ExecuteTemplate(&out, name, data); err != nil {
			return nil, fmt.Errorf("render %s: %w", name, err)
		}
	}
	return out.Bytes(), nil
}
package nexusbench

import (
	"context"
	"errors"
	"testing"
	"time"
)

// fakeClock is the Clock of the tests: Sleep never waits, it moves the clock
// forward by the requested duration. Destroy (step 7) and the readiness wait
// (step 4) run against it, so no test sleeps for real.
//
// Hypotheses about the Clock contract, which the real clock (clock.go) must keep:
//   - Sleep returns ctx.Err() as soon as ctx is done, before and instead of
//     sleeping, and nil after sleeping the whole duration;
//   - a caller never sleeps for zero or less (that would be a busy loop).
type fakeClock struct {
	t *testing.T

	now    time.Time
	sleeps []time.Duration // every Sleep call, in order

	// onSleep, when set, runs at the start of the n-th Sleep (1-based), before
	// ctx is looked at: a test cancels the context from it.
	onSleep func(n int)

	// maxSleeps stops a runaway loop: past it the fake reports the failure and
	// returns an error instead of letting the code under test spin forever.
	maxSleeps int
}

var _ Clock = (*fakeClock)(nil)

// fakeClockStart is the instant every fake clock starts at.
var fakeClockStart = time.Date(2026, time.November, 16, 12, 0, 0, 0, time.UTC)

func newFakeClock(t *testing.T) *fakeClock {
	t.Helper()
	return &fakeClock{t: t, now: fakeClockStart, maxSleeps: 5000}
}

// Now implements Clock.
func (c *fakeClock) Now() time.Time { return c.now }

// Sleep implements Clock.
func (c *fakeClock) Sleep(ctx context.Context, d time.Duration) error {
	c.t.Helper()
	c.sleeps = append(c.sleeps, d)
	if c.onSleep != nil {
		c.onSleep(len(c.sleeps))
	}
	if d <= 0 {
		c.t.Errorf("Sleep(%v): a wait must sleep for a positive duration", d)
	}
	if len(c.sleeps) > c.maxSleeps {
		c.t.Errorf("more than %d sleeps: the code under test loops without end", c.maxSleeps)
		return errors.New("fake clock: runaway loop")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	c.now = c.now.Add(d)
	return nil
}

// elapsed is how far the clock moved since it started.
func (c *fakeClock) elapsed() time.Duration { return c.now.Sub(fakeClockStart) }

func TestFakeClock(t *testing.T) {
	t.Run("sleeping moves the clock and records the duration", func(t *testing.T) {
		clk := newFakeClock(t)
		for _, d := range []time.Duration{2 * time.Second, 3 * time.Second} {
			if err := clk.Sleep(context.Background(), d); err != nil {
				t.Fatalf("Sleep(%v) = %v", d, err)
			}
		}
		if got, want := clk.elapsed(), 5*time.Second; got != want {
			t.Errorf("elapsed = %v, want %v", got, want)
		}
		if len(clk.sleeps) != 2 {
			t.Errorf("recorded %d sleeps, want 2", len(clk.sleeps))
		}
	})

	t.Run("a done context stops the sleep and leaves the clock alone", func(t *testing.T) {
		clk := newFakeClock(t)
		ctx, cancel := context.WithCancel(context.Background())
		cancel()
		if err := clk.Sleep(ctx, time.Second); !errors.Is(err, context.Canceled) {
			t.Errorf("Sleep with a cancelled context = %v, want context.Canceled", err)
		}
		if clk.elapsed() != 0 {
			t.Errorf("the clock moved by %v although the sleep was cancelled", clk.elapsed())
		}
	})

	t.Run("onSleep can cancel the context at the n-th sleep", func(t *testing.T) {
		clk := newFakeClock(t)
		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()
		clk.onSleep = func(n int) {
			if n == 2 {
				cancel()
			}
		}
		if err := clk.Sleep(ctx, time.Second); err != nil {
			t.Fatalf("first Sleep = %v", err)
		}
		if err := clk.Sleep(ctx, time.Second); !errors.Is(err, context.Canceled) {
			t.Errorf("second Sleep = %v, want context.Canceled", err)
		}
	})
}
