type Prober interface {
	Ready(ctx context.Context, baseURL string) error
}
type httpProber struct{ c *http.Client }

func NewProber() Prober {
	return httpProber{&http.Client{Timeout: 5 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}}
}
func (p httpProber) Ready(ctx context.Context, baseURL string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL+"/service/rest/v1/status", nil)
	if err != nil {
		return err
	}
	resp, err := p.c.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
	if resp.StatusCode != 200 {
		return fmt.Errorf("status %d", resp.StatusCode)
	}
	return nil
}

func Deploy(ctx context.Context, r Runner, pr Prober, clk Clock, p Params, out io.Writer) (DeployResult, error) {
	var res DeployResult
	if err := ctx.Err(); err != nil {
		return res, err
	}
	pf, err := RunPreflight(ctx, r, p, OpUp)
	if err != nil {
		return res, err
	}
	res.NodeIP = pf.NodeIP
	nsDoc, err := RenderNamespace(p)
	if err != nil {
		return res, err
	}
	full, _ := Render(p)
	for _, doc := range [][]byte{nsDoc, full} {
		if err := ctx.Err(); err != nil {
			return res, err
		}
		_, se, err := r.Run(ctx, doc, "apply", "--server-side", "--field-manager=devdesk-nexus-bench", "-f", "-")
		if err != nil {
			k := classifyKubectl(string(se))
			return res, &BenchError{Kind: k, Cause: "apply failed (" + map[ErrKind]string{NodePortTaken: "NEXUS_BENCH_HTTP_NODEPORT"}[k] + ")", Check: "kubectl apply", Err: err}
		}
	}
	hosts := p.Hosts
	if hosts == nil {
		hosts = []string{"127.0.0.1"}
		if pf.NodeIP != "" {
			hosts = append(hosts, pf.NodeIP)
		}
	}
	deadline := clk.Now().Add(p.Timeout)
	last := ""
	pvcBad := 0
	for {
		pods, _, err := r.Run(ctx, nil, "get", "pods", "-n", p.Namespace, "-l", "app.kubernetes.io/name=nexus", "-o", "json")
		if err != nil {
			return res, err
		}
		pvcs, _, err := r.Run(ctx, nil, "get", "pvc", "-n", p.Namespace, "-o", "json")
		if err != nil {
			return res, err
		}
		var pl struct {
			Items []struct {
				Metadata struct{ Name string }
				Status   struct {
					Phase      string
					Conditions []struct{ Type, Status, Reason, Message string }
					ContainerStatuses []struct {
						State struct {
							Waiting *struct{ Reason string }
							Running *struct{}
						}
						LastState struct{ Terminated *struct{ Reason string } }
					}
				}
			}
		}
		_ = json.Unmarshal(pods, &pl)
		var cl struct{ Items []struct{ Status struct{ Phase string } } }
		_ = json.Unmarshal(pvcs, &cl)
		last = "no pod yet"
		scheduled := false
		for _, it := range pl.Items {
			last = "pod " + it.Metadata.Name + " " + it.Status.Phase
			for _, c := range it.Status.Conditions {
				if c.Type == "PodScheduled" && c.Status == "True" {
					scheduled = true
				}
				if c.Type == "PodScheduled" && c.Status == "False" {
					m := strings.ToLower(c.Message)
					env, val := "NEXUS_BENCH_MEMORY_REQUEST", p.MemoryRequest
					if strings.Contains(m, "cpu") {
						env, val = "NEXUS_BENCH_CPU_REQUEST", p.CPURequest
					}
					return res, &BenchError{Kind: PodPending, Cause: "unschedulable: " + m + " (" + val + " " + env + ")", Check: "kubectl describe pod"}
				}
			}
			for _, cs := range it.Status.ContainerStatuses {
				if w := cs.State.Waiting; w != nil {
					last += " " + w.Reason
					if w.Reason == "ErrImagePull" || w.Reason == "ImagePullBackOff" {
						return res, &BenchError{Kind: ImagePull, Cause: "cannot pull " + p.ImageRef(), Check: "kubectl describe pod"}
					}
					if w.Reason == "CrashLoopBackOff" {
						return res, &BenchError{Kind: Crash, Cause: "CrashLoopBackOff, NEXUS_BENCH_MEMORY_LIMIT " + p.MemoryLimit + " OOMKilled?", Check: "kubectl logs"}
					}
				}
				if t := cs.LastState.Terminated; t != nil && t.Reason == "OOMKilled" {
					return res, &BenchError{Kind: Crash, Cause: "OOMKilled, NEXUS_BENCH_MEMORY_LIMIT " + p.MemoryLimit, Check: "kubectl logs"}
				}
			}
		}
		if scheduled && len(cl.Items) > 0 && cl.Items[0].Status.Phase == "Pending" {
			pvcBad++
			if pvcBad >= 3 {
				return res, &BenchError{Kind: PodPending, Cause: "storage claim Pending, NEXUS_BENCH_STORAGE_SIZE " + p.StorageSize, Check: "kubectl get pvc"}
			}
		} else {
			pvcBad = 0
		}
		for _, h := range hosts {
			if pr.Ready(ctx, "http://"+net.JoinHostPort(h, strconv.Itoa(p.HTTPNodePort))) == nil {
				res.ReachableHosts = append(res.ReachableHosts, h)
			}
		}
		if len(res.ReachableHosts) > 0 {
			for _, h := range hosts {
				found := false
				for _, r := range res.ReachableHosts {
					found = found || r == h
				}
				if !found {
					fmt.Fprintf(out, "warning: %s did not answer\n", h)
				}
			}
			return res, nil
		}
		if !clk.Now().Before(deadline) {
			return res, &BenchError{Kind: Deadline, Cause: "timed out (NEXUS_BENCH_TIMEOUT); last state: " + last + "; probed " + hosts[0], Check: "kubectl describe pod"}
		}
		if err := clk.Sleep(ctx, 5*time.Second); err != nil {
			return res, err
		}
	}
}
EOF
